CREATE TABLE IF NOT EXISTS loan_applications (id bigserial PRIMARY KEY, application_reference varchar(30) NOT NULL UNIQUE, customer_number varchar(30) NOT NULL, loan_type varchar(20) NOT NULL, status varchar(20) NOT NULL, requested_amount numeric(19,2) NOT NULL, tenure_months integer NOT NULL, annual_interest_rate numeric(7,3) NOT NULL, purpose varchar(500), reviewed_by varchar(30), rejection_reason varchar(500), submitted_at timestamp, reviewed_at timestamp, disbursed_at timestamp, created_at timestamp NOT NULL, updated_at timestamp NOT NULL); CREATE INDEX IF NOT EXISTS idx_loan_customer ON loan_applications(customer_number); CREATE INDEX IF NOT EXISTS idx_loan_status ON loan_applications(status); CREATE TABLE IF NOT EXISTS loan_repayments (id bigserial PRIMARY KEY, repayment_reference varchar(30) NOT NULL UNIQUE, loan_reference varchar(30) NOT NULL, installment_number integer NOT NULL, due_date date NOT NULL, due_amount numeric(19,2) NOT NULL, paid_amount numeric(19,2) NOT NULL, status varchar(20) NOT NULL, paid_date date, created_at timestamp NOT NULL); CREATE INDEX IF NOT EXISTS idx_repay_loan ON loan_repayments(loan_reference); CREATE INDEX IF NOT EXISTS idx_repay_status ON loan_repayments(status);
